-- private.recheck_member_takes(p_user uuid)
CREATE OR REPLACE FUNCTION private.recheck_member_takes(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  k    record;
  step integer;
  now_ timestamptz;
begin
  if p_user is null then return; end if;
  -- BK-E1B-S (CGR-255): the take's person lock before reading her takes, so a take of hers still in flight is waited
  -- for and then seen as committed (the serial outcome «take, then hand»).
  perform pg_advisory_xact_lock(hashtextextended('order_take_member:' || p_user::text, 0));
  -- ORDER-F1-F2 (pgTAP 179): the clock is read once (private.now() is security definer sql, never inlined; as a row filter
  -- it ran once per order row the plan visited); the start filter runs first (materialised), so take_visit_under_way
  -- reads care_visits only for takes of orders not yet started; and the query is planned at every call (execute), so a
  -- plan cached in this session while her takes were few is never reused once they are many. Same rows, same order.
  now_ := private.now();
  for k in execute
    'with live as materialized (
       select t.id, t.order_id, t.team_id, t.member_id, p.starts_at
       from public.order_takes t join public.partner_requests p on p.id = t.order_id
       where t.member_id = $1 and t.released_at is null and p.starts_at > $2)
     select l.id, l.order_id, l.team_id, l.member_id
     from live l
     where not private.take_visit_under_way(l.id)
     order by l.starts_at, l.id'  -- BK-E1B-R (CGR-244): never while her visit is under way
    using p_user, now_
  loop
    step := private.order_member_step(k.order_id, k.team_id, k.member_id);
    if step < 4 then
      update public.order_takes set released_at = private.now(), release_reason = 'step_' || step where id = k.id;
      -- CGR-223 (c): back to the broadcast after a fresh hard check of every team (the releasing team included).
      perform private.screen_order_reach(k.order_id, private.order_round(k.order_id) + 1);
    end if;
  end loop;
end;
$function$;

revoke all on function private.recheck_member_takes(p_user uuid) from public, anon, authenticated, service_role;
comment on function private.recheck_member_takes(p_user uuid) is 'BK-c1 (ADR-199 (5), CGR-223): releases every live take of the member before its start whose member no longer reaches step 4, and sends the order back to the broadcast. Never while her visit is under way (CGR-244). Takes the order_take_member person lock before reading (BK-e1b CGR-255, ADR-203 (20), marker BK-E1B-S). Internal.';
